INSERT INTO grade_history (history_id, grade_id, old_score, new_score, modified_by, reason)
SELECT h.history_id::uuid, h.grade_id::uuid, h.old_score::numeric, h.new_score::numeric, a.user_id, h.reason
FROM (VALUES
  ('72fb9d67-5138-5eaf-b65f-ce9a689ee028', '471bc8f1-3b4f-5fdc-8cff-dacbdca286f8', '12.00', '13.50', 'Correction after dispute')
) AS h(history_id, grade_id, old_score, new_score, reason)
