-- =====================================================================
-- Checks
-- =====================================================================
SELECT 'users' AS t, count(*) FROM users UNION ALL
SELECT 'students', count(*) FROM student UNION ALL
SELECT 'teachers', count(*) FROM teacher UNION ALL
SELECT 'courses', count(*) FROM course UNION ALL
SELECT 'groups', count(*) FROM groups UNION ALL
SELECT 'offerings', count(*) FROM course_offering UNION ALL
SELECT 'exams', count(*) FROM exam UNION ALL
SELECT 'grades', count(*) FROM grade UNION ALL
SELECT 'validations', count(*) FROM semester_credit_validation UNION ALL
SELECT 'transcripts', count(*) FROM transcript;

-- Sum of credits per (semester, track) must always be 30
SELECT ay.label, s.number, t.code, SUM(sub.credits) AS credits
FROM (SELECT DISTINCT o.semester_id, g.track_id, c.course_id, c.credits
      FROM course_offering o
      JOIN course c ON c.course_id = o.course_id
      JOIN groups g ON g.group_id = o.group_id) sub
JOIN semester s ON s.semester_id = sub.semester_id
JOIN academic_year ay ON ay.academic_year_id = s.academic_year_id
LEFT JOIN track t ON t.track_id = sub.track_id
GROUP BY ay.label, s.number, t.code
ORDER BY ay.label, s.number, t.code;